def boxes_and_lines(g):
    H,W=len(g),len(g[0])
    boxes=[]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c]:
                # find 3x3 box
                for dr in range(3):
                    for dc in range(3):
                        rr,cc=r+dr,c+dc
                        if rr<0 or cc<0 or H<=rr+3 or W<=cc+3: continue
                        sub=[g[i][j] for i in range(rr,rr+3) for j in range(cc,cc+3)]
                        if sub.count(3)==8 and sub.count(2)==1:
                            boxes.append(((rr+1,cc+1),sub))
                            for i in range(3): for j in range(3): seen[rr+i][cc+j]=True
    # lines: rows/cols of 2s (may be interrupted by boxes)
    rows_line=[r for r in range(H) if sum(1 for c in range(W) if g[r][c]==2)>W//3]
    cols_line=[c for c in range(W) if sum(1 for r in range(H) if g[r][c]==2)>H//3]
    return boxes,rows_line,cols_line

