    i,o=G[f'Demo pair {pair} input'],G[f'Demo pair {pair} output']
    H,W=len(i),len(i[0])
    boxes,rl,cl=boxes_and_lines(i)
    bg=lambda r,c: i[r][c]==0
    for bcenter,_ in boxes:
        cr,cc=bcenter
        # candidate centers
        cand=set()
        cand.add((cr,cc))
        if cl: cand.add((cr,[c for c in cl if c!=cc][0] if len([c for c in cl if c!=cc])==1 else None))
        if rl: cand.add(([r for r in rl if r!=cr][0] if len([r for r in rl if r!=cr])==1 else None,cc))
        results={}
        for cent in cand:
            if cent is None: continue
            rc,cc2=cent
            for shape,R in [('ring',3),('disk',3)]:
                cells=set()
                for dr in range(-R,R+1):
                    for dc in range(-R,R+1):
                        rr,ccc=rc+dr,cc2+dc
