            if g[r][c]==2:
                s=c
                while c<W and g[r][c]==2: c+=1
                hruns.append((r,s,c-1,c-s+1))
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==2:
                s=r
                while r<H and g[r][c]==2: r+=1
                vruns.append((c,s,r-1,r-s+1))
            else: r+=1
    horiz = any(run[3]>1 for run in hruns)  # length>1 horizontal run
    vert  = any(run[3]>1 for run in vruns)
    # boxes: connected components of 3 (8-conn)
    seen=[[False]*W for _ in range(H)]
    boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c]:
                comp=[]; st=[(r,c)]; seen[r][c]=True
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and g[nx][ny]==3 and not seen[nx][ny]:
                                seen[nx][ny]=True; st.append((nx,ny))
                cr=sum(x for x,y in comp)/len(comp); cc=sum(y for x,y in comp)/len(comp)
                rs=[x for x,y in comp]; cs=[y for x,y in comp]
                r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
                boxes.append(dict(center=(round(cr),round(cc)), r0=r0,r1=r1,c0=c0,c1=c1, cells=comp))
