                            if 0<=nx<H and 0<=ny<W and g[nx][ny]==3 and not seen[nx][ny]:
                                seen[nx][ny]=True; st.append((nx,ny))
                boxes.append(dict(comp=comp,r0=min(x for x,_ in comp),r1=max(x for x,_ in comp),
                                   c0=min(y for _,y in comp),c1=max(y for _,y in comp)))
