    hlen=max(r.count(2) for r in g); vlen=max(sum(g[r][c]==2 for r in range(H)) for c in range(W)) if W else 0
    vert = vlen >= hlen and hlen > 0 or hlen == 0 and vlen > 0
    o=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; comp=[]
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and g[nx][ny]==3 and not seen[nx][ny]:
                                seen[nx][ny]=True; st.append((nx,ny))
                boxes.append(comp)
    for b in boxes:
        brs=[x for x,_ in b]; bcs=[y for _,y in b]
        r0,r1=min(brs),max(brs); c0,c1=min(bcs),max(bcs)
        cr=(r0+r1)//2; cc=(c0+c1)//2
        if vert:
            for c_ in (cc-1,cc+1):
                for r_ in range(r0,r1+1):
                    if g[r_][c_]==0: o[r_][c_]=1
        else:
            for r_ in (cr-1,cr+1):
                for c_ in range(c0,c1+1):
