def runs(I,r,c,dr,dc):
    H=len(I);W=len(I[0]);n=0;cell=None
    while True:
        nr,nc=r+dr,c+dc
        if 0<=nr<H and 0<=nc<W and I[nr][nc]==2: n+=1; cell=(nr,nc)
        else: break
    return n

def f(I):
    H=len(I);W=len(I[0]); O=[[x for x in row] for row in I]
    seen=[[False]*W for _ in range(H)]; boxes=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==3 and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;cs=[]
                while st:
                    a,b=st.pop();cs.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and I[na][nb]==3 and not seen[na][nb]:
                                seen[na][nb]=True;st.append((na,nb))
                boxes.append((sum(a for a,_ in cs)//len(cs), sum(b for _,b in cs)//len(cs)))
    boxes=list(set(boxes))
    hlines=[r for r in range(H) if runs(I,r,0,0,1)>=3]
    vlines=[c for c in range(W) if runs(I,0,c,1,0)>=3]
    for (cr,cc) in boxes:
        # vertical arm col cc
        for r in range(H):
            if I[r][cc]==0: O[r][cc]=1
            elif I[r][cc]==2:
                # blocked by 2: paint flanks if 0, then continue below? simulate jump-over later
                pass
        # horizontal arm row cr
        for c in range(W):
            if I[cr][c]==0: O[cr][c]=1
            elif I[cr][c]==2:
                if I[cr][c-1]==0 and c-1>=0: O[cr][c-1]=1
                if I[cr][c+1]<W and I[cr][c+1]==0: O[cr][c+1]=1
    # hollow pluses at (hline, vboxcol) and (vboxrow, vline) where run>=3
    for (cr,cc) in boxes:
        for r in hlines:
            if I[r][cc]==2:
                for dc_ in (-1,1):
                    if 0<=cc+dc_<W and I[r][cc+dc_]==0: O[r][cc+dc_]=1
        for c in vlines:
            if I[cr][c]==2:
                for dr_ in (-1,1):
                    if 0<=cr+dr_<H and I[cr+dr_][c]==0: O[cr+dr_][c]=1
    # stubs between boxes
    for i in range(len(boxes)):
        for j in range(len(boxes)):
            if i==j: continue
            (a_,b_),=boxes[i]; (c_,d_),=boxes[j]
            a_line = next((r for r in hlines if I[r][b_]==2), None) or next((c for c in vlines if I[a_][c]==2), None)
            # stub on box i's own line at other box center row +/-1
            if a_line is not None:
                for s in (-1,1):
                    rr=c_+s
                    if 0<=rr<H and I[rr][a_line]==0: O[rr][a_line]=1
    return O

